const crypto = require('crypto');

const input = $input.first()?.json || {};
const workflowName = String(input.workflow?.name || 'Unknown Workflow');
const executionId = String(input.execution?.id || `exec_${Date.now()}`);
const failedNode = String(input.execution?.lastNodeExecuted || 'Unknown');
const rawError = String(
  input.execution?.error?.message ||
  input.execution?.error?.description ||
  'Workflow execution failed'
);
const errorMessage = rawError.slice(0, 300);
const idempotencyKey = `err:${workflowName}:${executionId}`;

const timestamp = String(Math.floor(Date.now() / 1000));
const rawBody = JSON.stringify({
  idempotencyKey,
  workflowName,
  errorMessage,
});

const secret = $env.CONVEX_AUTOMATION_SECRET || '';
if (!secret || secret.length < 16) {
  throw new Error('Missing or short CONVEX_AUTOMATION_SECRET environment variable (min 16 chars)');
}
const signatureHex = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

return [{
  json: {
    idempotencyKey,
    workflowName,
    executionId,
    failedNode,
    errorMessage,
    timestamp,
    signature: `sha256=${signatureHex}`,
    rawBody,
    alertSubject: `[LendLoop Automation Alert] Workflow Failure: ${workflowName}`,
    alertText: `LendLoop n8n workflow failure detected.\n\nWorkflow: ${workflowName}\nExecution ID: ${executionId}\nFailed Node: ${failedNode}\nError: ${errorMessage}\nTimestamp: ${new Date().toISOString()}`,
  },
}];
